module apbxclk #(
  parameter C_APB_ADDR_WIDTH = 12,
  parameter C_APB_DATA_WIDTH = 32,
  parameter [0:0] OPT_REGISTERED = 1'b0
)(
  input  wire                         S_APB_PCLK,
  input  wire                         S_PRESETn,
  input  wire                         S_APB_PSEL,
  input  wire                         S_APB_PENABLE,
  output reg                          S_APB_PREADY,
  input  wire [C_APB_ADDR_WIDTH-1:0]  S_APB_PADDR,
  input  wire                         S_APB_PWRITE,
  input  wire [C_APB_DATA_WIDTH-1:0]  S_APB_PWDATA,
  input  wire [C_APB_DATA_WIDTH/8-1:0] S_APB_PWSTRB,
  input  wire [2:0]                   S_APB_PPROT,
  output reg [C_APB_DATA_WIDTH-1:0]   S_APB_PRDATA,
  output reg                          S_APB_PSLVERR,

  input  wire                         M_APB_PCLK,
  output reg                          M_PRESETn,
  output reg                          M_APB_PSEL,
  output reg                          M_APB_PENABLE,
  input  wire                         M_APB_PREADY,
  output reg [C_APB_ADDR_WIDTH-1:0]   M_APB_PADDR,
  output reg                          M_APB_PWRITE,
  output reg [C_APB_DATA_WIDTH-1:0]   M_APB_PWDATA,
  output reg [C_APB_DATA_WIDTH/8-1:0] M_APB_PWSTRB,
  output reg [2:0]                    M_APB_PPROT,
  input  wire [C_APB_DATA_WIDTH-1:0]  M_APB_PRDATA,
  input  wire                         M_APB_PSLVERR
);

reg [C_APB_ADDR_WIDTH-1:0] req_addr;
reg req_write;
reg [C_APB_DATA_WIDTH-1:0] req_wdata;
reg [C_APB_DATA_WIDTH/8-1:0] req_wstrb;
reg [2:0] req_prot;
reg req_valid;
reg resp_valid;
reg [C_APB_DATA_WIDTH-1:0] resp_rdata;
reg resp_slverr;

always @(posedge S_APB_PCLK or negedge S_PRESETn) begin
  if (!S_PRESETn) begin
    M_PRESETn <= 1'b0;
    M_APB_PSEL <= 1'b0;
    M_APB_PENABLE <= 1'b0;
    req_valid <= 1'b0;
    resp_valid <= 1'b0;
    S_APB_PREADY <= 1'b0;
    S_APB_PRDATA <= {C_APB_DATA_WIDTH{1'b0}};
    S_APB_PSLVERR <= 1'b0;
  end else if (S_APB_PSEL && !S_APB_PENABLE) begin
    req_addr <= S_APB_PADDR;
    req_write <= S_APB_PWRITE;
    req_wdata <= S_APB_PWDATA;
    req_wstrb <= S_APB_PWSTRB;
    req_prot <= S_APB_PPROT;
    req_valid <= 1'b1;
  end else if (req_valid && M_APB_PREADY) begin
    req_valid <= 1'b0;
    resp_valid <= 1'b1;
    resp_rdata <= M_APB_PRDATA;
    S_APB_PSLVERR <= M_APB_PSLVERR;
  end else if (resp_valid && S_APB_PSEL && S_APB_PENABLE) begin
    resp_valid <= 1'b0;
    S_APB_PREADY <= 1'b1;
    S_APB_PRDATA <= resp_rdata;
  end else begin
    S_APB_PREADY <= 1'b0;
  end
end

always @(posedge M_APB_PCLK or negedge S_PRESETn) begin
  if (!S_PRESETn) begin
    M_PRESETn <= 1'b0;
    M_APB_PSEL <= 1'b0;
    M_APB_PENABLE <= 1'b0;
  end else if (req_valid) begin
    M_PRESETn <= S_PRESETn;
    M_APB_PSEL <= 1'b1;
    M_APB_PADDR <= req_addr;
    M_APB_PWRITE <= req_write;
    M_APB_PWDATA <= req_wdata;
    M_APB_PWSTRB <= req_wstrb;
    M_APB_PPROT <= req_prot;
    if (OPT_REGISTERED) begin
      M_APB_PENABLE <= 1'b1;
    end
  end else if (M_APB_PREADY) begin
    M_APB_PSEL <= 1'b0;
    M_APB_PENABLE <= 1'b0;
  end
end

always @(posedge M_APB_PCLK) begin
  if (OPT_REGISTERED && req_valid) begin
    M_APB_PENABLE <= 1'b1;
  end else if (M_APB_PREADY) begin
    M_APB_PENABLE <= 1'b0;
  end
end
